fn read_port(text: &str) -> Result<u16, ConfigError> {
    let port: u16 = text.parse()?;                      // ?: early return on Err
    let Some(rest) = text.strip_prefix("tcp") else {
        return Err(ConfigError::NotTcp);                // let-else: diverging guard
    };
    if rest.is_empty() || port == 0 {
        return Err(ConfigError::Invalid);               // classic guard
    }
    Ok(port)                                            // happy path stays flat
}
